turns.content:
{"t":"say","text":"I'll draw a private RAG assistant for employees: Qwen models via Model Studio, a vector store over your policy docs, and a simple internal UI."}
{"t":"plan","products":["users","alb","ecs","model-studio","milvus","oss","sls"]}
{"t":"assume","id":"scale","text":"About 500 internal employees","alt":"Over 5000 employees"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internal","kind":"external","label":"Internal users","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internal","why":"Staff asking policy and wiki questions."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes internal traffic to the app servers."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"app","product":"ecs","label":"RAG app servers","group":"vpc","zones":["a","b"],"why":"Runs the retrieval and Qwen prompt logic."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Hosted Qwen model for generating answers."}
{"t":"edge","id":"e-app-llm","from":"app","to":"llm","label":"Qwen API"}
{"t":"node","id":"vector","product":"milvus","label":"Milvus vector DB","group":"vpc","zones":["a","b"],"why":"Stores embeddings of policy and wiki chunks."}
{"t":"edge","id":"e-app-vector","from":"app","to":"vector","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"Policy documents","group":"sg","why":"Holds raw policy PDFs and wiki exports."}
{"t":"edge","id":"e-app-docs","from":"app","to":"docs","label":"read"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Captures queries and traces for debugging."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"doc-source","text":"Where do your policy documents and wiki live today?","options":["Files in OSS or NAS","Confluence or SharePoint","Custom database"]}
{"t":"ask","id":"ui-type","text":"How should employees access the assistant?","options":["Internal web portal","DingTalk bot","API only"]}
{"t":"done","summary":"Internal RAG assistant with ECS, Milvus, OSS and hosted Qwen via Model Studio behind an internal ALB."}

{"t":"say","text":"I'll draw a fully serverless REST API using Function Compute behind an API Gateway, scaling to zero for spiky traffic."}
{"t":"plan","products":["mobile-app","dns","cloud-native-api-gateway","fc","tablestore","oss","sls"]}
{"t":"req","text":"Pay only for what we use"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"assume","id":"auth","text":"API key auth at gateway","alt":"OAuth2 or JWT"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"app","product":"mobile-app","label":"Mobile app","group":"internet","why":"End users calling the REST API."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves API domain to the gateway."}
{"t":"edge","id":"e-app-dns","from":"app","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"API VPC","parent":"sg"}
{"t":"node","id":"gw","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Routes REST calls, throttles spikes, handles auth."}
{"t":"edge","id":"e-app-gw","from":"app","to":"gw","label":"HTTPS"}
{"t":"node","id":"api","product":"fc","label":"API functions","group":"vpc","why":"Serverless compute scales to zero, pay per request."}
{"t":"edge","id":"e-gw-api","from":"gw","to":"api","label":"invoke"}
{"t":"say","text":"Data goes to Tablestore for NoSQL storage and OSS for files, both serverless and usage-based."}
{"t":"node","id":"db","product":"tablestore","label":"Tablestore","group":"sg","why":"Serverless NoSQL database, billed per read/write unit."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"data"}
{"t":"node","id":"files","product":"oss","label":"Object storage","group":"sg","why":"Stores uploaded files, billed per GB and request."}
{"t":"edge","id":"e-api-files","from":"api","to":"files","label":"objects"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Centralized logs and metrics for the API functions."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"ask","id":"data-model","text":"What kind of data does the API store?","options":["User profiles and records","Time-series or IoT events","Files and media only"]}
{"t":"ask","id":"latency","text":"Where are most mobile users located?","options":["Southeast Asia","Worldwide","Single country"]}
{"t":"done","summary":"Serverless REST API with Cloud-native API Gateway, Function Compute, Tablestore and OSS, all paying only for usage."}

{"t":"say","text":"I'll draw an ACK cluster with MSE for discovery, Cloud-native API Gateway, RocketMQ, Tair cache and PolarDB."}
{"t":"plan","products":["users","dns","alb","cloud-native-api-gateway","ack","mse","rocketmq","tair","polardb","sls"]}
{"t":"assume","id":"exposure","text":"Public-facing API gateway","alt":"Internal only via VPC"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Clients","group":"internet","why":"Callers of the 20 microservices."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves API domain to ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Ingress load balancer across two zones."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Single entry point routing to services."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"ack","product":"ack","label":"ACK Cluster","group":"vpc","zones":["a","b"],"why":"Runs 20 Java microservices on Kubernetes."}
{"t":"edge","id":"e-gateway-ack","from":"gateway","to":"ack","label":"HTTP/gRPC"}
{"t":"node","id":"mse","product":"mse","label":"MSE Nacos","group":"vpc","why":"Service discovery and config for Java apps."}
{"t":"edge","id":"e-ack-mse","from":"ack","to":"mse","label":"discovery","kind":"control"}
{"t":"node","id":"mq","product":"rocketmq","label":"RocketMQ","group":"vpc","why":"Async messaging between microservices."}
{"t":"edge","id":"e-ack-mq","from":"ack","to":"mq","label":"events","kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Tair Cache","group":"vpc","zones":["a","b"],"why":"Shared cache with HA across zones."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache","label":"Redis"}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Relational database with read scaling."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Centralized logs and tracing."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"ask","id":"db-engine","text":"Which relational engine do your Java services use?","options":["MySQL","PostgreSQL","Oracle-compatible"]}
{"t":"ask","id":"scale","text":"What is the expected request volume?","options":["Under 1k RPS","1k-10k RPS","Over 10k RPS"]}
{"t":"done","summary":"ACK cluster with Cloud-native API Gateway, MSE Nacos, RocketMQ, Tair and PolarDB in Singapore."}

{"t":"say","text":"I'll design a highly available online store in Singapore with ESA, ALB, multi-zone ECS, Tair cache and PolarDB."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","polardb","oss","sls","cloudmonitor"]}
{"t":"req","text":"About 30,000 daily users with big sales peaks"}
{"t":"assume","id":"public-store","text":"Public-facing online store","alt":"Internal only"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"Customers browsing the store from Southeast Asia."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves the store domain to ESA edge nodes."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets, accelerates dynamic requests and provides DDoS defense for SEA shoppers."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Store VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Distributes traffic across two zones for high availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects checkout and login from bots and injection attacks."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the store backend across two zones for fault tolerance."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Adds instances automatically during big sales peaks."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sessions go to Tair and product data to PolarDB, both spanning two zones."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores sessions and hot cart data with low latency."}
{"t":"node","id":"db","product":"polardb","label":"Store database","group":"vpc","zones":["a","b"],"why":"Cloud-native DB with instant read scale-out for sales peaks."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Product images","group":"sg","why":"Stores product images and assets served through ESA."}
{"t":"edge","id":"e-esa-media","from":"esa","to":"media","label":"images"}
{"t":"say","text":"Adding monitoring and logging for operations visibility."}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Centralizes application logs for troubleshooting and alerts."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"node","id":"monitoring","product":"cloudmonitor","label":"CloudMonitor","group":"sg","why":"Monitors resource metrics and triggers alarms during peaks."}
{"t":"edge","id":"e-app-monitoring","from":"app","to":"monitoring","kind":"control"}
{"t":"ask","id":"peak-scale","text":"How many concurrent users do you expect during your biggest sales peaks?","options":["50,000","100,000","Over 200,000"]}
{"t":"ask","id":"payment-gateway","text":"Which payment gateway does the store use?","options":["Stripe","Adyen","Local provider"]}
{"t":"done","summary":"Highly available two-zone online store in Singapore with ESA, ALB with WAF, auto-scaling ECS, Tair cache and PolarDB."}

{"t":"say","text":"I'll draw a data platform that replicates MySQL in real time via DTS, runs nightly batch analytics on MaxCompute, and serves dashboards with Quick BI."}
{"t":"plan","products":["rds","dts","hologres","maxcompute","dataworks","quick-bi","sls"]}
{"t":"assume","id":"source-db","text":"Source is Alibaba Cloud RDS MySQL","alt":"On-premises or other-cloud MySQL"}
{"t":"assume","id":"region","text":"Deployed in Singapore (ap-southeast-1)","alt":"Another region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"orders-db","product":"rds","label":"Orders MySQL","group":"vpc","zones":["a","b"],"why":"Primary order database to replicate from."}
{"t":"node","id":"dts-sync","product":"dts","label":"DTS Real-time Sync","group":"sg","why":"Streams CDC changes from MySQL to the warehouse in real time."}
{"t":"edge","id":"e-orders-dts","from":"orders-db","to":"dts-sync","label":"CDC","kind":"data"}
{"t":"node","id":"holo-serve","product":"hologres","label":"Hologres Serving","group":"vpc","zones":["a","b"],"why":"Real-time analytical store fed by DTS for sub-second queries."}
{"t":"edge","id":"e-dts-holo","from":"dts-sync","to":"holo-serve","label":"sync","kind":"data"}
{"t":"node","id":"maxcompute-dw","product":"maxcompute","label":"MaxCompute Warehouse","group":"sg","why":"Stores historical data for nightly batch analytics."}
{"t":"edge","id":"e-dts-maxcompute","from":"dts-sync","to":"maxcompute-dw","label":"archive","kind":"async"}
{"t":"node","id":"dataworks-etl","product":"dataworks","label":"DataWorks","group":"sg","why":"Schedules nightly ETL jobs over MaxCompute tables."}
{"t":"edge","id":"e-dataworks-maxcompute","from":"dataworks-etl","to":"maxcompute-dw","label":"batch SQL","kind":"control"}
{"t":"node","id":"dashboards","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Gives business users interactive reports and dashboards."}
{"t":"edge","id":"e-dashboards-holo","from":"dashboards","to":"holo-serve","label":"live query","kind":"data"}
{"t":"edge","id":"e-dashboards-mc","from":"dashboards","to":"maxcompute-dw","label":"batch query","kind":"data"}
{"t":"ask","id":"source-location","text":"Where does your source MySQL database run today?","options":["Alibaba Cloud RDS","On-premises","AWS / Azure / GCP"]}
{"t":"ask","id":"latency-need","text":"How fresh must the dashboard data be?","options":["Real-time (seconds)","Hourly micro-batches","Nightly only"]}
{"t":"done","summary":"Data platform with RDS MySQL, DTS real-time sync to Hologres, MaxCompute for nightly batch via DataWorks, and Quick BI dashboards."}

{"t":"say","text":"I'll draw a hybrid setup with Express Connect linking your on-prem data center to a Singapore VPC, plus migration tools."}
{"t":"plan","products":["onprem-dc","express-connect","vpc","ecs","smc","dts","cloud-backup"]}
{"t":"assume","id":"link-type","text":"Dedicated private line via Express Connect","alt":"Quick IPsec tunnel via VPN Gateway"}
{"t":"assume","id":"db-migration","text":"Databases need migration alongside VMs","alt":"No database migration needed"}
{"t":"group","id":"onprem","kind":"onprem","label":"On-Premises Data Center","parent":null}
{"t":"node","id":"onprem-dc","product":"onprem-dc","label":"Singapore DC","group":"onprem","why":"Your existing data center hosting workloads to migrate."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Cloud VPC","parent":"sg"}
{"t":"node","id":"express-connect","product":"express-connect","label":"Express Connect","group":"vpc","why":"Private dedicated link between on-prem and cloud VPC."}
{"t":"edge","id":"e-onprem-express","from":"onprem-dc","to":"express-connect","label":"private link"}
{"t":"node","id":"ecs","product":"ecs","label":"Migrated VMs","group":"vpc","zones":["a","b"],"why":"Target compute instances for migrated workloads in two zones."}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Incrementally migrates on-prem VMs to ECS step by step."}
{"t":"edge","id":"e-smc-ecs","from":"smc","to":"ecs","label":"deploy","kind":"control"}
{"t":"node","id":"dts","product":"dts","label":"Data Transmission Service","group":"sg","why":"Migrates and syncs databases from on-prem to cloud."}
{"t":"edge","id":"e-dts-ecs","from":"dts","to":"ecs","label":"sync","kind":"data"}
{"t":"node","id":"cloud-backup","product":"cloud-backup","label":"Cloud Backup","group":"sg","why":"Protects migrated VMs with scheduled backups."}
{"t":"edge","id":"e-backup-ecs","from":"cloud-backup","to":"ecs","label":"backup","kind":"control"}
{"t":"ask","id":"vm-os","text":"What operating systems do your on-prem VMs run?","options":["Linux only","Windows only","Mixed Linux and Windows"]}
{"t":"ask","id":"database-type","text":"Which databases are you migrating?","options":["MySQL or PostgreSQL","SQL Server","Oracle","No databases"]}
{"t":"done","summary":"Hybrid architecture connecting your Singapore on-prem DC to Alibaba Cloud via Express Connect, with SMC and DTS for step-by-step VM and database migration."}

{"t":"say","text":"I'll draw an IoT telemetry pipeline: devices publish to IoT Platform, Flink detects anomalies in real time, and DataV powers the dashboard."}
{"t":"plan","products":["iot-devices","iot-platform","kafka","flink","tablestore","hologres","datav","sls","eventbridge"]}
{"t":"assume","id":"protocol","text":"Devices use MQTT over TLS","alt":"CoAP or HTTPS"}
{"t":"assume","id":"region","text":"Singapore region for all workloads","alt":"Another international region"}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100k IoT devices","group":"field","why":"Publish telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Telemetry VPC","parent":"sg"}
{"t":"node","id":"iot","product":"iot-platform","label":"IoT Platform","group":"sg","why":"Ingests and routes device telemetry via rules engine."}
{"t":"edge","id":"e-devices-iot","from":"devices","to":"iot","label":"MQTT"}
{"t":"node","id":"kafka","product":"kafka","label":"Kafka","group":"vpc","why":"Buffers high-throughput telemetry for stream processing."}
{"t":"edge","id":"e-iot-kafka","from":"iot","to":"kafka","label":"stream","kind":"async"}
{"t":"node","id":"flink","product":"flink","label":"Flink","group":"vpc","why":"Runs real-time anomaly detection on telemetry streams."}
{"t":"edge","id":"e-kafka-flink","from":"kafka","to":"flink","label":"consume"}
{"t":"node","id":"tsdb","product":"tablestore","label":"Tablestore","group":"vpc","why":"Stores raw time-series telemetry at massive scale."}
{"t":"edge","id":"e-flink-tsdb","from":"flink","to":"tsdb","label":"write"}
{"t":"node","id":"warehouse","product":"hologres","label":"Hologres","group":"vpc","why":"Serves aggregated metrics for the live dashboard."}
{"t":"edge","id":"e-flink-warehouse","from":"flink","to":"warehouse","label":"aggregates"}
{"t":"node","id":"alerts","product":"eventbridge","label":"EventBridge","group":"sg","why":"Routes detected anomalies as alert events downstream."}
{"t":"edge","id":"e-flink-alerts","from":"flink","to":"alerts","label":"anomalies","kind":"async"}
{"t":"node","id":"dashboard","product":"datav","label":"DataV dashboard","group":"sg","why":"Renders a live large-screen visualization of telemetry."}
{"t":"edge","id":"e-warehouse-dashboard","from":"warehouse","to":"dashboard","label":"query"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Collects pipeline logs and supports alert queries."}
{"t":"edge","id":"e-flink-logs","from":"flink","to":"logs","label":"logs","kind":"control"}
{"t":"ask","id":"alert-target","text":"Where should anomaly alerts be delivered?","options":["DingTalk webhook","SMS via SMS service","Custom HTTP endpoint","Email via Direct Mail"]}
{"t":"ask","id":"retention","text":"How long must raw telemetry be retained?","options":["7 days hot only","30 days in Tablestore","1 year with OSS cold tier"]}
{"t":"done","summary":"Real-time IoT pipeline: 100k devices to IoT Platform, Kafka buffering, Flink anomaly detection, Tablestore storage, Hologres serving and DataV dashboard."}

{"t":"say","text":"Qoder Teams is the right fit: it gives your 25 developers agentic coding assistance with SSO, admin controls and usage analytics."}
{"t":"rec","product":"qoder-teams","fit":"primary","why":"Agentic coding platform for teams with SSO, privacy mode, admin controls and usage analytics."}
{"t":"rec","product":"model-studio","fit":"complement","why":"Provides Qwen model APIs that power Qoder's coding agents."}
{"t":"done","summary":"Recommended Qoder Teams with Model Studio as the model backend for 25 developers needing SSO and admin controls."}

{"t":"say","text":"I'll draw a security layer for your e-commerce site using ESA, WAF, Captcha and Anti-DDoS Proxy."}
{"t":"plan","products":["users","dns","esa","anti-ddos-proxy","alb","waf","captcha","fraud-detection"]}
{"t":"assume","id":"existing-app","text":"App servers already exist behind an ALB","alt":"Draw full app stack"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers & Bots","group":"internet","why":"Traffic including legitimate users and attackers."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves shop domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge Security","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches content and provides built-in DDoS defense."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"node","id":"ddos","product":"anti-ddos-proxy","label":"Anti-DDoS Proxy","group":"edge","why":"Scrubs large L3-L7 DDoS attacks beyond ESA capacity."}
{"t":"edge","id":"e-esa-ddos","from":"esa","to":"ddos","label":"scrub"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Shop VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes traffic to existing app servers."}
{"t":"node","id":"waf","product":"waf","label":"WAF 3.0","group":"vpc","attachTo":"alb","why":"Blocks credential stuffing and OWASP attacks at the ALB."}
{"t":"edge","id":"e-ddos-alb","from":"ddos","to":"alb","label":"clean"}
{"t":"node","id":"captcha","product":"captcha","label":"Captcha","group":"sg","why":"Challenges bot sign-ups and suspicious login attempts."}
{"t":"node","id":"fraud","product":"fraud-detection","label":"Fraud Detection","group":"sg","why":"Risk scores accounts to stop fake sign-ups and takeovers."}
{"t":"edge","id":"e-captcha-fraud","from":"captcha","to":"fraud","label":"score"}
{"t":"ask","id":"current-ingress","text":"What currently fronts your application?","options":["ALB","ECS with EIP","Other cloud CDN"]}
{"t":"ask","id":"attack-size","text":"How large are the DDoS attacks you face?","options":["Under 10 Gbps","10-100 Gbps","Over 100 Gbps"]}
{"t":"done","summary":"E-commerce protection with ESA, Anti-DDoS Proxy, WAF on ALB, Captcha and Fraud Detection against bots and DDoS."}

{"t":"say","text":"I'll draw a secure multi-account landing zone with central identity, audit logging, threat detection and network firewalls."}
{"t":"plan","products":["acgc","resource-management","cloudsso","ram","idaas","actiontrail","sls","security-center","cloud-firewall","cloud-config"]}
{"t":"assume","id":"accounts","text":"New multi-account setup on Alibaba Cloud","alt":"Existing accounts to govern"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Shared VPC","parent":"sg"}
{"t":"say","text":"Starting with governance: landing zone, accounts and identity."}
{"t":"node","id":"landing-zone","product":"acgc","label":"Landing Zone","group":null,"why":"Automates multi-account setup with security baselines."}
{"t":"node","id":"rd","product":"resource-management","label":"Resource Directory","group":null,"why":"Organizes accounts into folders with guardrails."}
{"t":"edge","id":"e-landing-zone-rd","from":"landing-zone","to":"rd","label":"setup","kind":"control"}
{"t":"node","id":"sso","product":"cloudsso","label":"CloudSSO","group":null,"why":"Central SAML SSO across all managed accounts."}
{"t":"edge","id":"e-sso-rd","from":"sso","to":"rd","label":"provision","kind":"control"}
{"t":"node","id":"idaas","product":"idaas","label":"IDaaS","group":null,"why":"Corporate directory and MFA for workforce identity."}
{"t":"edge","id":"e-idaas-sso","from":"idaas","to":"sso","label":"SAML","kind":"control"}
{"t":"node","id":"ram","product":"ram","label":"RAM","group":null,"why":"Fine-grained roles and policies inside each account."}
{"t":"edge","id":"e-rd-ram","from":"rd","to":"ram","label":"policies","kind":"control"}
{"t":"say","text":"Now adding audit logging and compliance tracking."}
{"t":"node","id":"actiontrail","product":"actiontrail","label":"ActionTrail","group":null,"why":"Records every console and API action for audit."}
{"t":"edge","id":"e-rd-actiontrail","from":"rd","to":"actiontrail","label":"events","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Stores and analyzes audit logs centrally."}
